cat > pricing/pricing_test.go <<'EOF'
package pricing

import "testing"

func TestCartTotal(t *testing.T) {
	tests := []struct {
		name string
		cart Cart
		want int
	}{
		{
			name: "sums price times quantity across items",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 2},
					{Name: "book", Cents: 1200, Qty: 1},
				},
				Discount: &Discount{Percent: 0},
			},
			want: 1500,
		},
		{
			name: "applies percent discount to the sum",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 2},
					{Name: "book", Cents: 1200, Qty: 1},
				},
				Discount: &Discount{Percent: 10},
			},
			want: 1350,
		},
		{
			name: "truncates fractional discount cents",
			cart: Cart{
				Items:    []*Item{{Name: "gum", Cents: 99, Qty: 1}},
				Discount: &Discount{Percent: 15},
			},
			want: 85, // 99 - 14 (14.85 truncated)
		},
		{
			name: "no discount charges the full sum",
			cart: Cart{
				Items: []*Item{{Name: "pen", Cents: 150, Qty: 2}},
			},
			want: 300,
		},
		{
			name: "empty cart totals zero",
			cart: Cart{Discount: &Discount{Percent: 10}},
			want: 0,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.cart.Total(); got != tt.want {
				t.Errorf("Total() = %d, want %d", got, tt.want)
			}
		})
	}
}

func TestApplyDiscount(t *testing.T) {
	tests := []struct {
		name           string
		cents, percent int
		want           int
	}{
		{"zero percent leaves price unchanged", 1000, 0, 1000},
		{"reduces by percent", 1000, 25, 750},
		{"full discount yields zero", 1000, 100, 0},
		{"percent above 100 is capped and never goes below zero", 1000, 150, 0},
		{"truncates fractional discount cents", 99, 15, 85},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := ApplyDiscount(tt.cents, tt.percent); got != tt.want {
				t.Errorf("ApplyDiscount(%d, %d) = %d, want %d", tt.cents, tt.percent, got, tt.want)
			}
		})
	}
}
EOF
